    "kimlik_dogrulama": {
      "resmi_karsilastirma": {
        "ozet": "Uzun omurlu entegrasyon veya org adina erisim icin GitHub App oneriliyor; PAT'ler API testi/kisa scriptler icin. PAT kullaniciya bagli (kullanici erisimi kaybederse otomasyon kirilir); App kullaniciya bagli degil ve seat tuketmez. PAT gerekiyorsa fine-grained tercih edilmeli.",
        "alinti": "If you want to access GitHub resources on behalf of a user or in an organization, or you anticipate a long-lived integration, we recommend building a GitHub App.",
        "kaynak": "https://docs.github.com/en/apps/creating-github-apps/about-creating-github-apps/deciding-when-to-build-a-github-app#choosing-between-a-github-app-or-a-personal-access-token"
      },
      "installation_token_suresi_ve_kapsami": {
        "ozet": "Installation access token 1 saat gecerli. 'repositories' veya 'repository_ids' body parametresi ile token belirli repolara daraltilabilir (en fazla 500 repo); 'permissions' ile izinler daraltilabilir. Token, kurulumun sahip olmadigi repo/izni alamaz.",
        "alinti": "The installation access token will expire after 1 hour.",
        "endpoint": "POST /app/installations/{installation_id}/access_tokens",
        "kaynak": "https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-an-installation-access-token-for-a-github-app",
        "ek_kaynak": "https://docs.github.com/en/rest/apps/apps#create-an-installation-access-token-for-an-app"
      },
      "rate_limitler": {
        "ozet": "GitHub App installation token: min 5,000/saat; GHEC org'da 15,000/saat. GHEC disinda 20'den fazla repo icin repo basina +50, 20'den fazla kullanicili org'da kullanici basina +50; ust sinir 12,500/saat. PAT ve kullanici adina istekler: 5,000/saat (GHEC org'una ait App/OAuth app ile 15,000, ama ortak butceden duser). GITHUB_TOKEN: repo basina 1,000/saat (GHEC kaynaklarinda 15,000). Ikincil limitler: max 100 eszamanli istek; genelde dakikada 80 / saatte 500 icerik olusturan istek; REST icin dakikada 900 puan.",
        "alinti": "The rate limit cannot increase beyond 12,500 requests per hour.",
        "kaynak": "https://docs.github.com/en/rest/using-the-rest-api/rate-limits-for-the-rest-api#primary-rate-limit-for-github-app-installations",
        "ek_kaynak": [
          "https://docs.github.com/en/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits",
          "https://docs.github.com/en/apps/creating-github-apps/registering-a-github-app/rate-limits-for-github-apps"
        ]
      },
      "ince_taneli_izinler": {
        "ozet": "Ajan pipeline'i icin tipik App/fine-grained izinleri: Contents (kod okuma/yazma, HTTP Git erisimi), Pull requests, Checks (check run/suite REST API'si yalnizca GitHub App'lere acik; fine-grained PAT Checks API'yi cagiramaz), Workflows (.github/workflows dosyalarini degistirmek icin ayri izin), Statuses. Workflows izni PUT/DELETE contents, git refs olusturma/guncelleme gibi endpoint'lerde workflow dosyasi etkileniyorsa ek izin olarak gerekir.",
        "alinti": "If your app specifically needs to access or edit Actions files in the `.github/workflows` directory, request the \"Workflows\" repository permission.",
        "kaynak": "https://docs.github.com/en/apps/creating-github-apps/registering-a-github-app/choosing-permissions-for-a-github-app",
        "ek_kaynak": [
          "https://docs.github.com/en/rest/authentication/permissions-required-for-github-apps",
          "https://docs.github.com/en/apps/creating-github-apps/about-creating-github-apps/deciding-when-to-build-a-github-app#api-access-differs-slightly",
          "https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#fine-grained-personal-access-tokens-limitations"
        ]
      },
      "fine_grained_pat": {
        "ozet": "Tek kaynak sahibine (kullanici veya org) ve secili repolara sinirlanabilir; org'lar onay isteyebilir — varsayilan 'Require administrator approval' (org sahiplerinin token'lari haric). Onaylanana kadar token yalnizca public kaynaklari okur. Kullanici basina 50 fine-grained PAT limiti; otomasyon icin App oneriliyor. Org'larda fine-grained PAT icin varsayilan maksimum omur 366 gun. Eksikler: birden fazla org'a ayni anda erisim, Packages, Checks API, uye olunmayan public repolara katki vb.",
        "alinti": "There is a limit of 50 fine-grained personal access tokens you can create.",
        "kaynak": "https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#creating-a-fine-grained-personal-access-token",
        "ek_kaynak": "https://docs.github.com/en/organizations/managing-programmatic-access-to-your-organization/setting-a-personal-access-token-policy-for-your-organization#enforcing-an-approval-policy-for-fine-grained-personal-access-tokens"
      },
      "classic_pat": {
        "ozet": "Daha az guvenli; kullanicinin eristigi tum org'lardaki tum repolara ve kisisel repolara erisim verir. Onay politikasina tabi degil (org classic PAT erisimini kisitlamadikca). Bir yil kullanilmayan PAT'ler otomatik silinir.",
        "alinti": "it will grant access to all repositories within the organizations that you have access to",
        "kaynak": "https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#personal-access-tokens-classic",
        "ek_kaynak": "https://docs.github.com/en/organizations/managing-programmatic-access-to-your-organization/setting-a-personal-access-token-policy-for-your-organization"
      },
      "github_token_tetikleme": {
        "ozet": "GITHUB_TOKEN ile tetiklenen olaylar yeni workflow run'i olusturmaz; istisnalar: workflow_dispatch ve repository_dispatch her zaman calisir; GITHUB_TOKEN ile olusturulan/guncellenen PR'larin pull_request (opened/synchronize/reopened) olaylari 'approval-required' durumunda run olusturur ve write yetkili kullanici 'Approve workflows to run' ile baslatir. Otomatik calismasi icin App installation token veya PAT kullanilmali.",
        "alinti": "events triggered by the `GITHUB_TOKEN` will not create a new workflow run",
        "kaynak": "https://docs.github.com/en/actions/concepts/security/github_token#when-github_token-triggers-workflow-runs",
