      "github_token_pr_olusturma_onaylama": {
        "ozet": "Repo/org ayari 'Allow GitHub Actions to create and approve pull requests' ile GITHUB_TOKEN'in PR olusturma/onaylama yetkisi kontrol edilir; kisisel hesapta yeni repolarda varsayilan kapali. GitHub bunun gozetimsiz merge riskine dikkat cekiyor.",
        "alinti": "Allowing workflows, or any other automation, to create or approve pull requests could be a security risk",
        "kaynak": "https://docs.github.com/en/actions/reference/security/secure-use#preventing-github-actions-from-creating-or-approving-pull-requests",
        "ek_kaynak": "https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/enabling-features-for-your-repository/managing-github-actions-settings-for-a-repository"
      }
    },
    "branch_protection_rulesets": {
      "erisilebilirlik": {
        "ozet": "Rulesets: GitHub Free ve Free for organizations'da yalnizca PUBLIC repolarda; Pro, Team ve Enterprise Cloud'da public+private repolarda. Push rulesets: Team planinda internal/private repolarda. Klasik protected branches de ayni plan dagilimina sahip (+GHES). Repo basina 75, org genelinde 75 ruleset.",
        "alinti": "Rulesets are available in public repositories with GitHub Free and GitHub Free for organizations, and in public and private repositories with GitHub Pro, GitHub Team, and GitHub Enterprise Cloud.",
        "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/about-rulesets",
        "ek_kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"
      },
      "org_seviyesi_rulesets": {
        "ozet": "Belgeler arasinda tutarsizlik: 'Creating rulesets' sayfasi Team ve Enterprise planlarinda org-seviyesi ruleset diyor; 'About rulesets' ayni sayfada hem 'GitHub Team and GitHub Enterprise plans' hem 'For organizations on the GitHub Enterprise plan' ifadelerini kullaniyor. Team icin org-seviyesi ruleset kesinligi: dogrulanamadi (dokumanlar celisiyor).",
        "alinti": "For customers on GitHub Team and GitHub Enterprise plans you can also create rulesets for repositories in an organization.",
        "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/creating-rulesets-for-a-repository",
        "ek_kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/about-rulesets"
      },
      "rulesets_vs_branch_protection": {
        "ozet": "Ikisi birlikte calisir ve tum kurallar katmanlanir; ayni branch'e birden fazla ruleset uygulanabilir (klasikte tek kural), ruleset silmeden enforcement durumu degistirilebilir, read erisimi olan herkes aktif ruleset'leri gorebilir. Agustos 2026'dan beri klasik kurallar ayarlar ekranindan tek tikla ruleset'e donusturulebiliyor.",
        "alinti": "Multiple rulesets can apply to the same branch at the same time, while only one branch protection rule applies.",
        "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/about-rulesets#about-rulesets-and-protected-branches",
        "ek_kaynak": "https://github.blog/changelog/2026-08-11-automatically-migrate-branch-protection-rules-to-repository-rulesets"
      },
      "kurallar": {
        "require_pull_request": {
          "ozet": "Tum degisiklikler PR ile; zorunlu onay sayisi (write yetkili veya code owner), stale onaylarin dusurulmesi, code owner onayi, en son push'u yapan kisiden baska birinin onayi, tum yorumlarin cozulmesi, izin verilen merge tipi, review dismiss yetkisini kisitlama (Temmuz 2026), dosya/dizine gore team bazli 'Required reviewers' (kullanici sahipli repolarda yok).",
          "alinti": "you can require an approval from someone other than the last person to push to a branch before a pull request can be merged",
          "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/available-rules-for-rulesets#require-a-pull-request-before-merging"
        },
        "require_status_checks": {
          "ozet": "Strict (branch guncel olmali) / loose modlari. Write yetkili herhangi bir kisi/entegrasyon herhangi bir status'u set edebilir; bu yuzden beklenen kaynak olarak belirli bir GitHub App secilebilir (App statuses:write ile kurulu olmali ve yakin zamanda check run gondermis olmali).",
          "alinti": "Any person or integration with write permissions to a repository can set the state of any status check in the repository",
          "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/available-rules-for-rulesets#require-status-checks-to-pass-before-merging"
        },
        "block_force_pushes": {
          "ozet": "Varsayilan olarak etkin; engellenirse admin'ler de bypass yetkisi olmadan default branch'i degistiremez/yeniden adlandiramaz.",
          "alinti": "This rule is enabled by default.",
          "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/available-rules-for-rulesets#block-force-pushes"
        },
        "require_linear_history": {
          "ozet": "Merge commit push'u engellenir; PR'lar squash veya rebase ile merge edilmeli (repo bu yontemlere izin vermeli).",
          "alinti": "any pull requests merged into the branch or tag must use a squash merge or a rebase merge",
          "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/available-rules-for-rulesets#require-linear-history"
        },
        "require_merge_queue": {
          "ozet": "Yalnizca repo-seviyesi ruleset'lerde; plan kisiti merge queue ile ayni (org public repo veya GHEC private). Detay merge_queue bolumunde.",
