        }
      },
      "bypass_listesi": {
        "ozet": "Bypass edebilenler: repo admin/org owner/enterprise owner, maintain/write rolleri (veya write tabanli ozel roller), team'ler (secret team'ler haric), GitHub App'ler, Dependabot; Mayis 2026'dan itibaren repo-seviyesi ruleset'lerde tekil kullanicilar da. 'For pull requests only' secenegi ile aktor dogrudan push yerine PR acmaya zorlanir ama PR'da korumalari bypass edip merge edebilir. Klasik branch protection'da bypass listesi yalnizca org'a ait repolarda.",
        "alinti": "The selected actor is now required to open a pull request to make changes to a repository",
        "kaynak": "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/creating-rulesets-for-a-repository#granting-bypass-permissions-for-your-branch-or-tag-ruleset",
        "ek_kaynak": [
