          "https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches"
        ]
      },
      "kendi_pr_ini_onaylama": {
        "ozet": "PR yazari kendi PR'ini onaylayamaz. Bir GitHub App PR'i actiginda ayni kuralin App'e uygulanmasi genel kuraldan cikarimdir (App'e ozel ayri bir ifade bulunamadi). Copilot onaylari zorunlu onay sayisina SAYILMAZ. Genel bir GitHub App'in onayinin zorunlu onay sayisina sayilip sayilmadigi: dogrulanamadi. Admin/owner'lar onay olmadan merge edebilir (bypass kapatilmadikca).",
        "alinti": "Pull request authors cannot approve their own pull requests.",
        "kaynak": "https://docs.github.com/en/pull-requests/how-tos/review-pull-requests/approving-a-pull-request-with-required-reviews"
      }
    },
    "referans_ajan_oruntuleri": {
      "copilot_cloud_agent_kontrolleri": {
        "ozet": "GitHub'in kendi ajani (Copilot coding agent, 2026 dokumanlarinda 'Copilot cloud agent') icin resmi hafifletmeler: yalnizca tek branch'e push (yeni 'copilot/' branch'i veya @copilot ile cagrildigi PR'in branch'i), branch protection ve required check'lere tabi; dogrudan 'git push' calistiramaz; draft PR'lari insan inceleyip merge etmeli, ajan 'Ready for review' yapamaz/onaylayamaz/merge edemez; varsayilan olarak Actions workflow'lari write yetkili bir kullanici 'Approve and run workflows' diyene kadar calismaz (istege bagli kapatilabilir); gorevi veren kisi PR'i onaylayamaz; kisiye atfedilmemis PR'larda +1 onay; internet erisimi firewall ile kisitli; issue/yorumlardaki gizli karakterler/HTML yorumlari filtrelenir; her commit mesaji oturum loguna link verir.",
        "alinti": "Copilot cloud agent cannot mark its pull requests as \"Ready for review\" and cannot approve or merge a pull request.",
        "ek_alinti": "By default, workflows are not triggered until Copilot cloud agent's code is reviewed",
        "kaynak": "https://docs.github.com/en/copilot/concepts/security-governance-and-network-settings/risks-and-mitigations"
      },
      "copilot_limitler": {
        "ozet": "Gorev basina tek repo, tek branch, tek PR; oturum basina 59 dakika sert limit; ruleset/branch protection uyumsuzsa (ör. yalnizca belirli commit author'larina izin) ajan engellenir — ruleset'te Copilot bypass aktoru olarak eklenebilir.",
        "alinti": "Each Copilot cloud agent session has a maximum execution time of 59 minutes",
        "kaynak": "https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent#limitations-of-copilot-cloud-agent"
      },
      "copilot_self_hosted_runner": {
        "ozet": "Copilot ajani self-hosted runner'da calisabilir; GitHub yalnizca ephemeral, tek kullanimlik runner oneriyor (ARC veya Runner Scale Set Client). Self-hosted'da Copilot'un entegre firewall'u uyumsuz ve kapatilmasi gerekiyor (ag kontrolunu siz saglamalisiniz). Nisan 2026'dan beri org admin'leri varsayilan runner'i org genelinde belirleyip kilitleyebiliyor.",
        "alinti": "We recommend that you only use Copilot cloud agent with ephemeral, single-use runners that are not reused for multiple jobs.",
        "kaynak": "https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-cloud-agent/customize-the-agent-environment#using-self-hosted-github-actions-runners",
        "ek_kaynak": [
          "https://github.blog/changelog/2025-10-28-copilot-coding-agent-now-supports-self-hosted-runners",
          "https://github.blog/changelog/2026-04-03-organization-runner-controls-for-copilot-cloud-agent"
        ]
      },
      "otomasyon_zinciri": {
